'use strict';
/* Prototipo académico: todas las operaciones son locales, sin cuentas reales. */
const $ = (s,r=document)=>r.querySelector(s);
const escapeHTML = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const asset = (node,name)=>DESIGN_ASSETS[node+':'+name];
const img = (node,name,alt='',extra='')=>`<img src="${asset(node,name)}" alt="${escapeHTML(alt)}" ${extra}>`;
const KEY='comunidad-upn-ihc-v1';
const initial={user:null,posts:[],businesses:[],questions:[],replies:{},registrations:[],saved:[],reports:[],read:[],settings:{name:'Estudiante UPN',large:false,notices:true}};
let state;
try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');state={...structuredClone(initial),...raw,settings:{...initial.settings,...raw?.settings}};for(const k of ['posts','businesses','questions','registrations','saved','reports','read'])if(!Array.isArray(state[k]))state[k]=[];if(!state.replies||typeof state.replies!=='object')state.replies={};}catch{state=structuredClone(initial);}
let storageWarned=false;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{if(!storageWarned){storageWarned=true;toast('El navegador no permite guardar. Tus cambios durarán mientras la página siga abierta.');}}}
const categories=[['avisos','✦','Avisos','Comunicados','cream'],['eventos','▣','Eventos','Talleres y charlas','pink'],['foro','◆','Consultas','Apoyo académico','blue'],['emprendimientos','◈','Emprendimientos','Negocios de alumnos','green'],['becas','✿','Becas','Oportunidades','purple'],['vida','☀','Vida universitaria','Clubes y amigos','orange']];
const nav=[['inicio','⌂','Inicio'],['avisos','✦','Avisos'],['eventos','▣','Eventos'],['foro','▢','Foro académico'],['publicaciones','▤','Publicaciones'],['emprendimientos','◈','Emprendimientos'],['categorias','⊞','Categorías'],['moderacion','♜','Moderación']];
const events=[{id:'e1',title:'Feria de empleabilidad',day:'05',cat:'Empleabilidad',place:'Campus Trujillo',time:'10:00 a. m.',description:'Conoce oportunidades profesionales, conversa con empresas y participa en orientación para tus próximas prácticas.',image:'imgFrame5'},{id:'e2',title:'Hackathon UPN',day:'06',cat:'Tecnología',place:'Auditorio universitario',time:'9:00 a. m.',description:'Forma un equipo, desarrolla una solución y comparte tus ideas con otros estudiantes. Lleva tu laptop y muchas ganas de crear.',image:'imgFrame6'},{id:'e3',title:'Festival UPN Cultural',day:'12',cat:'Culturales',place:'Plaza central',time:'4:00 p. m.',description:'Disfruta de una jornada de música, arte y expresiones culturales de nuestra comunidad.',image:'imgFrame5'},{id:'e4',title:'Taller de currículum',day:'07',cat:'Empleabilidad',place:'Campus Trujillo',time:'11:00 a. m.',description:'Aprende a presentar tu experiencia y preparar un currículum claro para tus primeras oportunidades.',image:'imgFrame7'},{id:'e5',title:'Charla sobre IA',day:'08',cat:'Académicos',place:'Sala de innovación',time:'3:00 p. m.',description:'Explora aplicaciones de la inteligencia artificial y reflexiona sobre su uso responsable en el aprendizaje.',image:'imgFrame6'},{id:'e6',title:'Feria de clubes',day:'09',cat:'Culturales',place:'Campus Trujillo',time:'2:00 p. m.',description:'Descubre clubes, conoce a sus integrantes y encuentra actividades que se conecten con tus intereses.',image:'imgFrame5'}];
const notices=[{id:'a1',title:'Matrícula 2027-I',subtitle:'Cronograma y requisitos para estudiantes',description:'Revisa tu turno y los requisitos antes de iniciar la matrícula. Este comunicado es un ejemplo académico: confirma siempre la información oficial en los canales de tu universidad.',cat:'Matrícula'},{id:'a2',title:'Cambio de aula',subtitle:'Actualizaciones de ambientes y horarios',description:'Consulta los ambientes asignados a tus cursos antes de asistir a clases. Los cambios presentados aquí son datos de demostración.',cat:'Académicos'},{id:'a3',title:'Convocatoria de becas',subtitle:'Fechas y beneficios disponibles',description:'Consulta las oportunidades y reúne la documentación de postulación. Los requisitos y fechas de este prototipo son ilustrativos.',cat:'Becas'}];
const baseQuestions=[{id:'q1',title:'Duda sobre wireframes',cat:'Interacción Humano Computador',description:'¿Cómo puedo diferenciar un wireframe de un prototipo de alta fidelidad para nuestro proyecto de IHC?',author:'Lucía Castro',base:12},{id:'q2',title:'Ayuda con SQL',cat:'Ingeniería de Sistemas',description:'¿En qué casos conviene usar una clave foránea compuesta? Me ayudaría un ejemplo sencillo.',author:'Andrés Flores',base:8},{id:'q3',title:'Grupo de estudio',cat:'Cálculo I',description:'Busco compañeros para organizar un grupo de repaso. ¿Qué temas les gustaría practicar?',author:'Valeria Reyes',base:15}];
const baseBusinesses=[{id:'b1',title:'Lume Velas',cat:'Artesanía',description:'Velas artesanales para regalar y acompañar tus espacios de estudio.',contact:'lume@ejemplo.com',image:'imgFrame2',owner:false},{id:'b2',title:'StudyHub',cat:'Servicios',description:'Recursos digitales y materiales para organizar tu aprendizaje.',contact:'studyhub@ejemplo.com',image:'imgFrame3',owner:false},{id:'b3',title:'NutriSnack',cat:'Alimentos',description:'Snacks saludables para acompañarte entre clases.',contact:'nutrisnack@ejemplo.com',image:'imgFrame4',owner:false},{id:'b4',title:'Dulce Campus',cat:'Alimentos',description:'Pastelería y regalos para tus momentos especiales.',contact:'dulce@ejemplo.com',image:'imgFrame2',owner:false},{id:'b5',title:'PrintLab',cat:'Servicios',description:'Impresiones y artículos personalizados para estudiantes.',contact:'printlab@ejemplo.com',image:'imgFrame3',owner:false},{id:'b6',title:'TechFix',cat:'Tecnología',description:'Soporte técnico para estudiantes y sus equipos.',contact:'techfix@ejemplo.com',image:'imgFrame4',owner:false}];
const opportunities=[{id:'k1',title:'Beca Excelencia',description:'Reconoce el esfuerzo y rendimiento académico. Consulta los requisitos vigentes por los canales oficiales de UPN.'},{id:'k2',title:'Prácticas preprofesionales',description:'Prepara tu currículum e identifica oportunidades relacionadas con tu carrera. La información aquí es demostrativa.'},{id:'k3',title:'Concursos universitarios',description:'Comparte tus ideas y participa en retos académicos. Revisa las bases de cada convocatoria oficial.'}];
const clubs=[{id:'v1',title:'Club de programación',description:'Un espacio para practicar, crear proyectos y compartir conocimientos con otros estudiantes.'},{id:'v2',title:'Voluntariado UPN',description:'Conecta con iniciativas de participación y servicio a la comunidad.'},{id:'v3',title:'Club cultural',description:'Comparte tus intereses por el arte, la música y las actividades culturales.'}];
const content=$('#content'),dialog=$('#dialog');let route='',filter='Todos',query='',globalQuery='',lastFocus=null,toastTimer;
const allQuestions=()=>[...state.questions,...baseQuestions];
const allBusinesses=()=>[...state.businesses,...baseBusinesses];
const normalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const matches=(item,q)=>normalize([item.title,item.cat,item.description,item.subtitle].join(' ')).includes(normalize(q));
const uid=prefix=>prefix+'-'+(globalThis.crypto?.randomUUID?.()||Date.now()+'-'+Math.random().toString(36).slice(2));
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function initials(name){return name.split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase()||'UP';}
function shell(){document.body.classList.toggle('large-text',state.settings.large);const active=route==='nuevo-emprendimiento'?'emprendimientos':route==='nueva-publicacion'?'publicaciones':route;
$('#sidebar').innerHTML=`<button class="icon-button mobile-close" data-action="menu-close" aria-label="Cerrar menú">×</button><a class="brand" href="#${state.user?'inicio':'acceso'}">${img('2:66','imgFrame','')}<span>Comunidad<br>UPN</span></a><nav class="nav">${nav.map(([r,i,t])=>`<a href="#${r}" class="${active===r?'active':''}" ${active===r?'aria-current="page"':''}><span class="icon" aria-hidden="true">${i}</span>${t}</a>`).join('')}</nav><div><div class="side-label">AYUDA Y PERFIL</div><a href="#ayuda" class="side-extra">ⓘ &nbsp; Ayuda</a><a href="#configuracion" class="side-extra">⚙ &nbsp; Configuración</a>${state.user?'<a href="#acceso" class="side-extra" data-action="logout">↪ &nbsp; Cerrar sesión</a>':''}</div><div class="slogan">Una comunidad,<p>muchas oportunidades.</p><small>✦ CONECTA · CREA</small></div>`;
$('#header').innerHTML=`<button class="icon-button menu-button" data-action="menu" aria-label="Abrir menú" aria-controls="sidebar" aria-expanded="false">☰</button><div class="header-title"><h2>Comunidad universitaria</h2><p>Conecta, aprende, participa y haz crecer tu experiencia UPN.</p></div><form class="global-search" id="global-search" role="search"><label class="sr-only" for="global-input">Buscar en Comunidad UPN</label><input id="global-input" type="search" name="q" maxlength="100" placeholder="⌕ Buscar en Comunidad UPN…" value="${escapeHTML(globalQuery)}"></form><button class="icon-button" data-action="notifications" aria-label="Ver notificaciones">♧</button><button class="avatar" data-action="profile" aria-label="${state.user?'Ver perfil':'Iniciar sesión'}">${escapeHTML(state.user?initials(state.settings.name):'UP')}</button>`;
}
function hero(eyebrow,title,description,node,name,button){return `<section class="hero"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p>${button||'<a href="#categorias" class="primary">Explorar la comunidad →</a>'}</div><div class="hero-art">${node?img(node,name,''):''}</div></section>`;}
function categoryTiles(large=false){return `<div class="category-grid ${large?'category-page':''}">${categories.map(([r,i,t,s,c])=>`<a href="#${r}" class="category ${c}"><span class="icon" aria-hidden="true">${i}</span><strong>${t}</strong><small>${s}</small>${large?'<span class="text-link">Explorar →</span>':''}</a>`).join('')}</div>`;}
function eventMini(e){return `<button class="event-mini" data-action="event" data-id="${e.id}"><span class="date"><b>${e.day}</b><small>NOV</small></span>${img('2:66',e.image)}<span><h3>${e.title}</h3><p>${e.place}</p></span></button>`;}
function home(){return `<section class="hero home-hero"><div><div class="eyebrow">COMUNIDAD UPN</div><h1>Más que una<br>universidad,<br>una comunidad.</h1><p>Conecta con otros estudiantes, descubre oportunidades,<br>participa en eventos y haz realidad tus ideas.</p><a class="primary" href="#categorias">Explorar la comunidad →</a></div><div class="hero-art"><div class="art-window"><div class="layered-art">${HOME_ILLUSTRATION}</div></div></div></section><div class="section-head"><h2>Explora por categorías</h2><a class="text-link" href="#categorias">Ver todas →</a></div>${categoryTiles()}<div class="dashboard-row"><section class="panel"><h2>✦ Emprendimientos destacados</h2><div class="business-grid">${baseBusinesses.slice(0,3).map(b=>`<button class="business" data-action="business" data-id="${b.id}">${img('2:66',b.image)}<h3>${b.title}</h3><p>${b.cat==='Alimentos'?'Snacks saludables':b.cat==='Servicios'?'Recursos digitales':'Velas artesanales'}</p></button>`).join('')}</div></section><section class="panel"><h2>▣ Próximos eventos</h2>${[events[0],events[1],events[3]].map(eventMini).join('')}</section></div><div class="bottom-grid"><section class="panel"><h2>✿ Becas destacadas</h2><button class="feature" data-action="opportunity" data-id="k1">${img('2:66','imgFrame8')}<span><h3>Beca Excelencia UPN</h3><p>Reconocemos tu esfuerzo.</p></span></button></section><section class="panel"><h2>◆ Apoyo académico</h2>${baseQuestions.map((q,i)=>`<button class="thread-mini" data-action="question" data-id="${q.id}"><span class="initials ${['cream','blue','green'][i]}">${initials(q.author)}</span>${q.title}</button>`).join('')}</section><section class="panel"><h2>☀ Vida universitaria</h2><a class="feature" href="#vida">${img('22:539','imgIlustracionExclusivaCampus')}<h3>Clubes, amigos<br>y experiencias</h3></a></section></div>`;}
function toolbar(cats,placeholder,extra=''){return `<div class="toolbar"><label class="sr-only" for="local-search">${placeholder}</label><input class="search" id="local-search" type="search" placeholder="${placeholder}" maxlength="100" value="${escapeHTML(query)}">${extra}</div>${cats.length?`<div class="toolbar" aria-label="Filtros">${cats.map(c=>`<button class="chip ${filter===c?'active':''}" aria-pressed="${filter===c}" data-action="filter" data-value="${c}">${c}</button>`).join('')}</div>`:''}`;}
function empty(message='No encontramos resultados.'){return `<div class="empty"><h3>${message}</h3><p>Prueba con otra palabra o cambia los filtros.</p><button class="secondary" data-action="clear-filters">Limpiar filtros</button></div>`;}
function resultCount(n){return `<p class="count" role="status">${n} ${n===1?'resultado':'resultados'}</p>`;}
function results(){let list;
switch(route){case 'eventos':list=events.filter(e=>matches(e,query)&&(filter==='Todos'||filter==='Mis inscripciones'&&state.registrations.includes(e.id)||e.cat===filter));return resultCount(list.length)+`<div class="cards">${list.map(e=>`<article class="card"><div class="card-visual">${img('2:66',e.image)}<span class="date"><b>${e.day}</b><small>NOV</small></span></div><div class="card-body"><span class="badge ${state.registrations.includes(e.id)?'green':''}">${state.registrations.includes(e.id)?'INSCRITO':e.cat.toUpperCase()}</span><h3>${e.title}</h3><small>${e.place} · ${e.time}</small><p>${e.description}</p><button class="soft" data-action="event" data-id="${e.id}">Ver detalles →</button></div></article>`).join('')||empty()}</div>`;
case 'avisos':list=notices.filter(a=>matches(a,query)&&(filter==='Todos'||a.cat===filter));return resultCount(list.length)+`<div class="list">${list.map((a,i)=>`<article class="list-item"><span class="list-icon" aria-hidden="true">${['▣','◆','✿'][i]}</span><div class="body"><h3>${a.title}</h3><p>${a.subtitle}</p><small>${state.read.includes(a.id)?'Leído':'Sin leer'} · ${a.cat}</small></div><span class="badge">OFICIAL · EJEMPLO</span><button class="secondary" data-action="notice" data-id="${a.id}">Leer aviso →</button></article>`).join('')||empty()}</div>`;
case 'foro':list=allQuestions().filter(q=>matches(q,query)&&(filter==='Todos'||q.cat===filter));return resultCount(list.length)+`<div class="list">${list.map(q=>`<article class="list-item"><span class="initials blue">${escapeHTML(initials(q.author))}</span><div class="body"><h3>${escapeHTML(q.title)}</h3><p>${escapeHTML(q.cat)} · ${(q.base||0)+(state.replies[q.id]?.length||0)} respuestas</p><small>${escapeHTML(q.author)}</small></div><button class="secondary" data-action="question" data-id="${q.id}">Ver consulta →</button></article>`).join('')||empty()}</div>`;
case 'emprendimientos':list=allBusinesses().filter(b=>matches(b,query)&&(filter==='Todos'||b.cat===filter||filter==='Mis emprendimientos'&&b.owner));return resultCount(list.length)+`<div class="cards">${list.map(b=>`<article class="card"><div class="card-visual ${b.cat==='Alimentos'?'green':b.cat==='Artesanía'?'cream':'blue'}">${img('2:66',b.image)}</div><div class="card-body"><span class="badge">${escapeHTML(b.cat)}</span><h3>${escapeHTML(b.title)}</h3><p>${escapeHTML(b.description)}</p><button class="soft" data-action="business" data-id="${escapeHTML(b.id)}">Ver emprendimiento →</button></div></article>`).join('')||empty()}</div>`;
case 'publicaciones':list=state.posts.filter(p=>matches(p,query)&&(filter==='Todas'||filter==='Guardadas'&&state.saved.includes(p.id)||p.cat===filter));return resultCount(list.length)+`<div class="list">${list.map(p=>`<article class="list-item"><span class="initials purple">${escapeHTML(initials(p.author))}</span><div class="body"><span class="badge">${escapeHTML(p.cat)}</span><h3>${escapeHTML(p.title)}</h3><p>${escapeHTML(p.description.slice(0,120))}${p.description.length>120?'…':''}</p><small>${escapeHTML(p.author)}</small></div><button class="secondary" data-action="post" data-id="${p.id}">Ver publicación →</button></article>`).join('')||'<div class="empty"><h3>Todavía no hay publicaciones aquí</h3><p>Comparte una idea, un recurso o una experiencia con tu comunidad.</p><a href="#nueva-publicacion" class="primary">Crear publicación</a></div>'}</div>`;
case 'buscar':{const items=[...events.map(x=>({...x,type:'event',label:'Evento'})),...notices.map(x=>({...x,type:'notice',label:'Aviso'})),...allQuestions().map(x=>({...x,type:'question',label:'Consulta'})),...allBusinesses().map(x=>({...x,type:'business',label:'Emprendimiento'})),...state.posts.map(x=>({...x,type:'post',label:'Publicación'})),...opportunities.map(x=>({...x,type:'opportunity',label:'Beca'})),...clubs.map(x=>({...x,type:'club',label:'Vida universitaria'}))].filter(x=>matches(x,globalQuery));return resultCount(items.length)+`<div class="list">${items.map(x=>`<article class="list-item"><div class="body"><span class="badge">${x.label}</span><h3>${escapeHTML(x.title)}</h3><p>${escapeHTML((x.description||x.subtitle||'').slice(0,100))}</p></div><button class="secondary" data-action="${x.type}" data-id="${x.id}">Abrir →</button></article>`).join('')||empty('No hay coincidencias para tu búsqueda.')}</div>`;}
default:return '';}}
function listingPage(){const config={avisos:['COMUNICADOS','Avisos institucionales','Mantente al día con noticias oficiales.','2:129','imgIlustracionExclusivaEvent',['Todos','Matrícula','Académicos','Becas'],'Buscar comunicados…'],eventos:['VIVE TU COMUNIDAD','Eventos universitarios','Conecta, aprende y participa.','2:199','imgIlustracionExclusivaChat',['Todos','Académicos','Culturales','Tecnología','Empleabilidad','Mis inscripciones'],'Buscar eventos…'],foro:['APRENDEMOS JUNTOS','Foro académico','Pregunta, comparte y aprende con tu comunidad.','2:267','imgFrame1',['Todos','Interacción Humano Computador','Ingeniería de Sistemas','Cálculo I'],'Buscar consultas…'],emprendimientos:['TALENTO UPN','Explorar emprendimientos','Descubre y apoya las ideas de nuestros estudiantes.','2:451','imgIlustracionExclusivaSafety',['Todos','Alimentos','Artesanía','Servicios','Tecnología','Mis emprendimientos'],'Buscar emprendimientos…'],publicaciones:['COMPARTE CON TU COMUNIDAD','Publicaciones','Tus ideas también construyen nuestra comunidad.','2:2','imgIlustracionExclusivaBooks',['Todas','Académico','Vida universitaria','Oportunidades','Guardadas'],'Buscar publicaciones…']}[route];
const [eyebrow,title,description,node,name,cats,placeholder]=config;const extra=route==='foro'?'<button class="primary" data-action="new-question">+ Nueva consulta</button>':route==='emprendimientos'?'<a class="primary" href="#nuevo-emprendimiento">+ Publicar emprendimiento</a>':route==='publicaciones'?'<a class="primary" href="#nueva-publicacion">+ Crear publicación</a>':'';
return hero(eyebrow,title,description,node,name)+toolbar(cats,placeholder,extra)+'<section id="results" aria-label="Resultados">'+results()+'</section>';}
function field(label,name,type='text',placeholder='',extra=''){return `<div class="field ${type==='textarea'?'full':''}"><label for="${name}">${label} <span class="required" aria-hidden="true">*</span></label>${type==='textarea'?`<textarea id="${name}" name="${name}" required maxlength="1500" minlength="10" placeholder="${placeholder}" ${extra}></textarea><small>Mínimo 10 caracteres. <span id="char-count">0</span>/1500</small>`:type==='select'?`<select id="${name}" name="${name}" required ${extra}><option value="">Selecciona una categoría</option>${placeholder.split('|').map(s=>`<option>${s}</option>`).join('')}</select>`:`<input id="${name}" name="${name}" type="${type}" required placeholder="${placeholder}" ${extra}>`}</div>`;}
function authorPage(business=false){const key=business?'business':'post';return hero('COMPARTE TU TALENTO',business?'Publicar emprendimiento':'Crear publicación',business?'Haz crecer tus ideas junto a tu comunidad.':'Comparte ideas, recursos y experiencias con otros estudiantes.',business?'2:396':'2:2',business?'imgIlustracionExclusivaStartup':'imgIlustracionExclusivaBooks')+`<section class="panel form-panel"><h2>${business?'Registra tu emprendimiento':'Nueva publicación'}</h2><p class="small">Los campos con <span class="required">*</span> son obligatorios.</p><div class="hint">${business?'Describe tu propuesta con claridad y utiliza un contacto de demostración.':'Cuida la información personal y comparte contenido respetuoso y útil.'}</div><form id="author-form" data-kind="${key}"><div class="form-grid">${field('Título','title','text',business?'Nombre de tu emprendimiento':'Un título claro para tu comunidad','minlength="5" maxlength="80"')}${field('Categoría','cat','select',business?'Alimentos|Artesanía|Servicios|Tecnología':'Académico|Vida universitaria|Oportunidades')}${field('Descripción','description','textarea',business?'¿Qué ofreces y qué hace especial tu propuesta?':'Escribe lo que quieres compartir…')}${business?field('Contacto','contact','email','emprendimiento@ejemplo.com','maxlength="120"'):''}</div><p id="form-error" class="error" role="alert"></p><div class="form-actions"><button class="secondary" type="button" data-action="cancel-author">Cancelar</button><button class="secondary" type="button" data-action="preview-author">Vista previa</button><button class="primary" type="submit">Publicar →</button></div></form></section>`;}
function login(){return `<section class="login-layout"><div><div class="eyebrow">COMUNIDAD UPN</div><h1>¡Bienvenido a tu<br>comunidad universitaria!</h1><p>Estudiantes, ideas y oportunidades en un solo lugar.</p><form id="login-form" class="login-form" novalidate><h2>Ingresa con tu correo UPN</h2><div class="field"><label for="email">Correo institucional</label><input id="email" name="email" type="email" autocomplete="username" placeholder="usuario@upn.edu.pe" required maxlength="120" aria-describedby="login-error"></div><div class="field"><label for="password">Contraseña de demostración</label><div class="password-wrap"><input id="password" name="password" type="password" autocomplete="off" placeholder="Mínimo 6 caracteres" required minlength="6" maxlength="80" aria-describedby="login-error"><button type="button" class="icon-button" data-action="password" aria-label="Mostrar contraseña" aria-pressed="false">◉</button></div></div><p id="login-error" class="error" role="alert"></p><button class="primary" type="submit">Ingresar a Comunidad UPN →</button><div class="login-help"><button type="button" class="text-link" data-action="demo-credentials">Usar datos de prueba</button><button type="button" class="text-link" data-action="guest">Explorar como invitado</button></div><small>Acceso simulado. No uses tu contraseña real de UPN.</small></form></div><div class="login-visual"><h2>✦ Comparte ideas</h2><h2>✦ Descubre eventos</h2><h2>✦ Impulsa tus proyectos</h2>${img('2:2','imgIlustracionExclusivaBooks')}<h3>Una comunidad, muchas oportunidades.</h3></div></section>`;}
function infoPage(kind){const scholarship=kind==='becas';const list=scholarship?opportunities:clubs;return hero('EXPLORA POR CATEGORÍAS',scholarship?'Becas y oportunidades':'Vida universitaria','Descubre información, oportunidades y estudiantes que comparten tus intereses.',scholarship?'22:467':'22:539',scholarship?'imgIlustracionExclusivaScholarship':'imgIlustracionExclusivaCampus')+'<a class="soft" href="#categorias">← Todas las categorías</a><div class="section-head"><h2>Contenido destacado</h2></div><div class="cards">'+list.map(i=>`<article class="card"><div class="card-visual">${img(scholarship?'22:467':'22:539',scholarship?'imgIlustracionExclusivaScholarship':'imgIlustracionExclusivaCampus')}</div><div class="card-body"><h3>${i.title}</h3><p>${i.description}</p><button class="soft" data-action="${scholarship?'opportunity':'club'}" data-id="${i.id}">Ver información →</button></div></article>`).join('')+'</div>';}
function moderation(){return hero('CUIDAMOS NUESTRA COMUNIDAD','Moderación y reportes','Un espacio seguro se construye con respeto y participación.','2:451','imgIlustracionExclusivaSafety')+`<div class="hint">Vista académica: las acciones se aplican únicamente a los datos de este navegador. Los reportes no se envían a UPN.</div><section class="panel"><h2>Reportes recibidos</h2>${state.reports.length?'<div class="list">'+state.reports.map(r=>`<article class="list-item"><div class="body"><span class="badge ${r.status==='Revisado'?'green':''}">${r.status}</span><h3>${escapeHTML(r.title)}</h3><p>Motivo: ${escapeHTML(r.reason)}</p></div>${r.status==='Pendiente'?`<button class="secondary" data-action="resolve-report" data-id="${r.id}">Marcar revisado</button>`:''}</article>`).join('')+'</div>':'<div class="empty"><h3>No hay reportes pendientes</h3><p>Puedes reportar una publicación desde su detalle.</p></div>'}</section><section class="panel" style="margin-top:15px"><h2>Acuerdos de convivencia</h2><p>Respeta las opiniones, evita compartir información personal de otros y publica contenido relacionado con la vida universitaria. Un desacuerdo por sí solo no constituye una falta.</p></section>`;}
function settings(){return `<section class="panel settings"><div class="eyebrow">AYUDA Y PERFIL</div><h1 style="font-size:28px">Configuración</h1><p style="margin:12px 0 22px">Personaliza tu experiencia en esta comunidad.</p><form id="settings-form"><div class="field"><label for="display-name">Nombre para mostrar</label><input id="display-name" name="name" value="${escapeHTML(state.settings.name)}" maxlength="50" minlength="2" required></div><label class="toggle-row"><span><strong>Texto más grande</strong><p>Aumenta el tamaño base de lectura.</p></span><input type="checkbox" name="large" ${state.settings.large?'checked':''}></label><label class="toggle-row"><span><strong>Avisos de la comunidad</strong><p>Muestra notificaciones de ejemplo dentro del prototipo.</p></span><input type="checkbox" name="notices" ${state.settings.notices?'checked':''}></label><button class="primary">Guardar cambios</button></form><div class="section-head"><h2>Datos de demostración</h2></div><p>Tus publicaciones, respuestas, reportes e inscripciones se conservan solo en este navegador.</p><button class="danger" style="margin-top:15px" data-action="reset">Restablecer demostración</button></section>`;}
function help(){return `<section class="panel settings"><div class="eyebrow">ESTAMOS PARA AYUDARTE</div><h1 style="font-size:30px">Ayuda</h1>${[['¿Cómo ingreso?','Utiliza el botón “Usar datos de prueba” en la pantalla de acceso. No necesitas una cuenta real. También puedes explorar como invitado.'],['¿Cómo participo en un evento?','Entra a Eventos, abre el detalle y selecciona “Inscribirme”. Encontrarás el evento en “Mis inscripciones”. Puedes cancelar desde su detalle.'],['¿Cómo hago una consulta?','Entra al Foro académico y selecciona “Nueva consulta”. Completa el título, el curso y tu pregunta. Las respuestas se agregan desde el detalle.'],['¿Cómo publico un emprendimiento?','En Emprendimientos selecciona “Publicar emprendimiento”, completa los campos y revisa la vista previa antes de publicar.'],['¿Dónde se guarda la información?','El prototipo conserva datos de demostración en este navegador mediante localStorage, cuando está disponible. No se comparte información con otras personas.'],['¿Cómo navego con el teclado?','Usa Tab para recorrer controles, Enter para activarlos y Escape para cerrar ventanas. Al abrir la página, puedes usar “Saltar al contenido”.']].map(([q,a])=>`<details class="faq"><summary>${q}</summary><p>${a}</p></details>`).join('')}</section>`;}
function render(){shell();switch(route){case 'acceso':content.innerHTML=login();break;case 'inicio':content.innerHTML=home();break;case 'avisos':case 'eventos':case 'foro':case 'emprendimientos':case 'publicaciones':content.innerHTML=listingPage();break;case 'categorias':content.innerHTML=hero('EXPLORA TU COMUNIDAD','Explorar categorías','Encuentra actividades, información y personas que comparten tus intereses.','2:605','imgIlustracionExclusivaEvent')+categoryTiles(true);break;case 'nuevo-emprendimiento':content.innerHTML=authorPage(true);break;case 'nueva-publicacion':content.innerHTML=authorPage();break;case 'becas':case 'vida':content.innerHTML=infoPage(route);break;case 'moderacion':content.innerHTML=moderation();break;case 'configuracion':content.innerHTML=settings();break;case 'ayuda':content.innerHTML=help();break;case 'buscar':content.innerHTML=`<div class="section-head"><h1 style="font-size:28px">Resultados de búsqueda</h1></div><p>Buscaste: <strong>${escapeHTML(globalQuery)}</strong></p><section id="results" style="margin-top:20px">${results()}</section>`;break;default:content.innerHTML='<div class="empty"><h1>Página no encontrada</h1><a class="primary" href="#inicio">Volver al inicio</a></div>';}
scaleArt();document.title=(nav.find(x=>x[0]===route)?.[2]||({'acceso':'Acceso','nuevo-emprendimiento':'Publicar emprendimiento','nueva-publicacion':'Crear publicación','ayuda':'Ayuda','configuracion':'Configuración','becas':'Becas','vida':'Vida universitaria','buscar':'Buscar'}[route])||'Comunidad')+' · Comunidad UPN';}
function scaleArt(){const el=$('.layered-art');if(!el)return;const width=el.closest('.hero-art').clientWidth,height=el.closest('.hero-art').clientHeight,scale=Math.min(width/632,height/238);el.style.transform=`scale(${scale})`;const wrapper=el.parentElement;wrapper.style.width=632*scale+'px';wrapper.style.height=238*scale+'px';}
window.addEventListener('resize',scaleArt);
function navigate(){if(dialog.open)dialog.close();const hash=location.hash.slice(1);if(hash.startsWith('buscar'))globalQuery=new URLSearchParams(hash.split('?')[1]||'').get('q')||'';const next=hash.split('?')[0]||(state.user?'inicio':'acceso');route=next;filter=route==='publicaciones'?'Todas':'Todos';query='';render();window.scrollTo(0,0);content.focus({preventScroll:true});}
window.addEventListener('hashchange',navigate);
function go(r){if(location.hash==='#'+r){navigate();}else location.hash=r;}
function openDialog(title,body,actions=''){if(!dialog.open)lastFocus=document.activeElement;dialog.innerHTML=`<div class="dialog-top"><h2 id="dialog-title">${escapeHTML(title)}</h2><button class="icon-button" data-action="close" aria-label="Cerrar ventana">×</button></div>${body}${actions?'<div class="dialog-actions">'+actions+'</div>':''}`;if(!dialog.open)dialog.showModal();}
dialog.addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus();});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
function requireUser(callback){if(state.user){callback();return;}openDialog('Participa en tu comunidad','<p>Ingresa con los datos de prueba para publicar, responder o inscribirte. No necesitas una cuenta real.</p>','<button class="secondary" data-action="close">Seguir explorando</button><a class="primary" href="#acceso">Ir al acceso</a>');}
function showEvent(id){const e=events.find(x=>x.id===id);if(!e)return;const registered=state.registrations.includes(id);openDialog(e.title,`${img('2:66',e.image,'','class="detail-image"')}<span class="badge">${e.cat}</span><div class="detail-meta">${e.day} de noviembre de 2026 · ${e.time}<br>${e.place}</div><p class="detail-copy">${e.description}</p><div class="hint">${registered?'Ya estás inscrito en este evento de demostración.':'Inscripción de prueba. No se envían datos a organizadores.'}</div>`,`<button class="secondary" data-action="close">Cerrar</button><button class="${registered?'danger':'primary'}" data-action="${registered?'cancel-registration':'register'}" data-id="${id}">${registered?'Cancelar inscripción':'Inscribirme →'}</button>`);}
function showQuestion(id){const q=allQuestions().find(x=>x.id===id);if(!q)return;const replies=state.replies[id]||[];openDialog(q.title,`<div class="detail-meta">${escapeHTML(q.author)} · ${escapeHTML(q.cat)}</div><p class="detail-copy">${escapeHTML(q.description)}</p><h3 style="margin:22px 0 10px">Respuestas de esta demostración (${replies.length})</h3>${replies.map(r=>`<article class="reply"><h3>${escapeHTML(r.author)}</h3><p>${escapeHTML(r.description)}</p></article>`).join('')||'<p class="small">Sé la primera persona en responder aquí.</p>'}${q.base?'<p class="saved-note">El contador inicial del Figma es ilustrativo; aquí aparecen las respuestas que agregues.</p>':''}<form class="reply-form" id="reply-form" data-id="${id}"><label for="reply">Tu respuesta</label><textarea id="reply" name="description" required minlength="5" maxlength="1000" placeholder="Comparte una respuesta útil y respetuosa…"></textarea><button class="primary">Enviar respuesta</button></form>`);}
function showBusiness(id){const b=allBusinesses().find(x=>x.id===id);if(!b)return;openDialog(b.title,`${img('2:66',b.image,'','class="detail-image"')}<span class="badge">${escapeHTML(b.cat)}</span><p class="detail-copy" style="margin:15px 0">${escapeHTML(b.description)}</p><div class="business-contact"><strong>Contacto de demostración</strong><br>${escapeHTML(b.contact)}</div>`,`${b.owner?`<button class="danger" data-action="delete-business" data-id="${id}">Eliminar mi emprendimiento</button>`:''}<button class="primary" data-action="close">Entendido</button>`);}
function showPost(id){const p=state.posts.find(x=>x.id===id);if(!p)return;openDialog(p.title,`<span class="badge">${escapeHTML(p.cat)}</span><div class="detail-meta">${escapeHTML(p.author)}</div><p class="detail-copy">${escapeHTML(p.description)}</p>`,`<button class="secondary" data-action="save-post" data-id="${id}">${state.saved.includes(id)?'Quitar de guardadas':'Guardar publicación'}</button><button class="secondary" data-action="report-post" data-id="${id}">Reportar</button><button class="danger" data-action="delete-post" data-id="${id}">Eliminar mi publicación</button>`);}
function newQuestion(){requireUser(()=>openDialog('Nueva consulta',`<form id="question-form"><div class="form-grid">${field('Título','q-title','text','¿Sobre qué necesitas ayuda?','minlength="5" maxlength="80"')}${field('Curso','q-cat','select','Interacción Humano Computador|Ingeniería de Sistemas|Cálculo I')}${field('Consulta','q-description','textarea','Explica tu duda para que otros puedan ayudarte…')}</div><div class="dialog-actions"><button class="secondary" type="button" data-action="close">Cancelar</button><button class="primary">Publicar consulta</button></div></form>`));}
function authorData(){const f=$('#author-form');if(!f.reportValidity())return null;const data=Object.fromEntries(new FormData(f));for(const k in data)data[k]=data[k].trim();if(data.title.length<5||data.description.length<10){$('#form-error').textContent='Escribe un título de al menos 5 caracteres y una descripción de al menos 10, sin contar espacios exteriores.';return null;}return data;}
function refreshResults(){if($('#results'))$('#results').innerHTML=results();}
function confirmDelete(kind,id){openDialog('Confirmar eliminación','<p>Se eliminará este contenido de tu demostración. Esta acción no se puede deshacer.</p>',`<button class="secondary" data-action="close">Conservar</button><button class="danger" data-action="confirm-delete" data-kind="${kind}" data-id="${id}">Eliminar</button>`);}
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();content.focus();return;}const el=e.target.closest('[data-action]');if(!el)return;const {action,id,value,kind}=el.dataset;
switch(action){case 'menu':$('#sidebar').classList.add('open');el.setAttribute('aria-expanded','true');$('.mobile-close').focus();break;case 'menu-close':$('#sidebar').classList.remove('open');$('.menu-button')?.setAttribute('aria-expanded','false');$('.menu-button')?.focus();break;case 'close':dialog.close();break;case 'profile':if(!state.user){go('acceso');break;}openDialog('Tu perfil',`<div class="initials cream" style="width:60px;height:60px;font-size:20px;margin-bottom:15px">${escapeHTML(initials(state.settings.name))}</div><h3>${escapeHTML(state.settings.name)}</h3><p>${escapeHTML(state.user.email)}</p><div class="hint">${state.registrations.length} inscripciones · ${state.posts.length} publicaciones</div>`,'<a class="secondary" href="#configuracion">Configuración</a><button class="primary" data-action="close">Cerrar</button>');break;case 'notifications':openDialog('Notificaciones',state.settings.notices?'<p>Explora los próximos eventos y las nuevas oportunidades de tu comunidad.</p><div class="hint">Estas notificaciones son ejemplos del prototipo.</div>':'<p>Has desactivado los avisos de la comunidad. Puedes activarlos en Configuración.</p>','<a class="primary" href="#eventos">Ver eventos</a>');break;case 'password':{const input=$('#password');const show=input.type==='password';input.type=show?'text':'password';el.setAttribute('aria-label',show?'Ocultar contraseña':'Mostrar contraseña');el.setAttribute('aria-pressed',String(show));break;}case 'demo-credentials':$('#email').value='estudiante@upn.edu.pe';$('#password').value='DemoUPN2026';$('#login-error').textContent='';toast('Datos de prueba listos. Pulsa Ingresar.');break;case 'guest':go('inicio');break;case 'logout':state.user=null;persist();break;case 'filter':filter=value;document.querySelectorAll('[data-action="filter"]').forEach(x=>{x.classList.toggle('active',x.dataset.value===filter);x.setAttribute('aria-pressed',String(x.dataset.value===filter));});refreshResults();break;case 'clear-filters':filter=route==='publicaciones'?'Todas':'Todos';query='';if(route==='buscar'){globalQuery='';go('categorias');}else render();break;case 'event':showEvent(id);break;case 'register':requireUser(()=>{if(!state.registrations.includes(id))state.registrations.push(id);persist();showEvent(id);refreshResults();toast('Inscripción registrada en tu demostración.');});break;case 'cancel-registration':openDialog('¿Cancelar tu inscripción?','<p>Podrás volver a inscribirte cuando lo desees en esta demostración.</p>',`<button class="secondary" data-action="event" data-id="${id}">Mantener inscripción</button><button class="danger" data-action="confirm-cancel" data-id="${id}">Cancelar inscripción</button>`);break;case 'confirm-cancel':state.registrations=state.registrations.filter(x=>x!==id);persist();showEvent(id);refreshResults();toast('Inscripción cancelada.');break;case 'notice':{const n=notices.find(x=>x.id===id);if(!state.read.includes(id))state.read.push(id);persist();openDialog(n.title,`<span class="badge">COMUNICADO DE EJEMPLO</span><p class="detail-copy" style="margin-top:15px">${n.description}</p>`,'<button class="primary" data-action="close">Entendido</button>');refreshResults();break;}case 'question':showQuestion(id);break;case 'new-question':newQuestion();break;case 'business':showBusiness(id);break;case 'post':showPost(id);break;case 'opportunity':case 'club':{const item=(action==='club'?clubs:opportunities).find(x=>x.id===id);openDialog(item.title,`<p class="detail-copy">${item.description}</p><div class="hint">Información ilustrativa. Consulta los canales oficiales para confirmar convocatorias y actividades.</div>`,'<button class="primary" data-action="close">Entendido</button>');break;}case 'preview-author':{const data=authorData();if(data)openDialog('Vista previa',`<div class="preview-box"><span class="badge">${escapeHTML(data.cat)}</span><h3 style="margin:10px 0">${escapeHTML(data.title)}</h3><p class="detail-copy">${escapeHTML(data.description)}</p>${data.contact?'<p style="margin-top:15px">'+escapeHTML(data.contact)+'</p>':''}</div>`,'<button class="primary" data-action="close">Seguir editando</button>');break;}case 'cancel-author':{const f=$('#author-form');if([...f.querySelectorAll('input,textarea,select')].some(x=>x.value))openDialog('¿Descartar el borrador?','<p>Los cambios que aún no publicaste se perderán.</p>','<button class="secondary" data-action="close">Seguir editando</button><a class="danger" href="#'+(f.dataset.kind==='business'?'emprendimientos':'publicaciones')+'">Descartar borrador</a>');else go(f.dataset.kind==='business'?'emprendimientos':'publicaciones');break;}case 'save-post':if(state.saved.includes(id))state.saved=state.saved.filter(x=>x!==id);else state.saved.push(id);persist();showPost(id);refreshResults();toast('Publicaciones guardadas actualizadas.');break;case 'report-post':{const p=state.posts.find(x=>x.id===id);openDialog('Reportar publicación',`<form id="report-form" data-id="${id}"><p style="margin-bottom:15px">${escapeHTML(p.title)}</p><div class="field"><label for="reason">Motivo del reporte</label><select id="reason" name="reason" required><option value="">Selecciona un motivo</option>Contenido ofensivo</option><option>Información engañosa</option><option>Datos personales expuestos</option><option>Publicidad no relacionada</option></select></div><div class="dialog-actions"><button class="secondary" data-action="close" type="button">Cancelar</button><button class="primary">Enviar reporte de prueba</button></div></form>`);break;}case 'resolve-report':{const r=state.reports.find(x=>x.id===id);if(r)r.status='Revisado';persist();render();toast('Reporte marcado como revisado.');break;}case 'delete-post':confirmDelete('posts',id);break;case 'delete-business':confirmDelete('businesses',id);break;case 'confirm-delete':if(!['posts','businesses'].includes(kind))break;state[kind]=state[kind].filter(x=>x.id!==id);state.saved=state.saved.filter(x=>x!==id);persist();dialog.close();render();toast('Contenido eliminado.');break;case 'reset':openDialog('¿Restablecer la demostración?','<p>Se eliminarán tus publicaciones, emprendimientos, consultas, respuestas, inscripciones y ajustes de este navegador.</p>','<button class="secondary" data-action="close">Conservar mis datos</button><button class="danger" data-action="confirm-reset">Restablecer</button>');break;case 'confirm-reset':state=structuredClone(initial);persist();dialog.close();go('acceso');toast('Demostración restablecida.');break;}
});
document.addEventListener('input',e=>{if(e.target.id==='local-search'){query=e.target.value;refreshResults();}if(e.target.id==='description'){const n=$('#char-count');if(n)n.textContent=e.target.value.length;}if(['email','password'].includes(e.target.id)){$('#login-error').textContent='';e.target.removeAttribute('aria-invalid');}});
document.addEventListener('submit',e=>{const form=e.target;if(!['login-form','global-search','author-form','question-form','reply-form','settings-form','report-form'].includes(form.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(form));switch(form.id){case 'login-form':{const email=data.email.trim(),password=data.password;if(!email||!password){$('#login-error').textContent='Completa el correo y la contraseña de demostración.';(!email?$('#email'):$('#password')).focus();break;}if(!/^[A-Z0-9.!#$%&'*+\/=?^_`{|}~-]+@(?:upn\.edu\.pe|upn\.pe)$/i.test(email)){$('#login-error').textContent='Utiliza un correo con dominio @upn.edu.pe o @upn.pe.';$('#email').setAttribute('aria-invalid','true');$('#email').focus();break;}if(password.length<6){$('#login-error').textContent='La contraseña de demostración debe tener al menos 6 caracteres.';$('#password').setAttribute('aria-invalid','true');$('#password').focus();break;}state.user={email};persist();go('inicio');toast('¡Bienvenido a tu comunidad!');break;}case 'global-search':globalQuery=data.q.trim();if(globalQuery)go('buscar?q='+encodeURIComponent(globalQuery));else toast('Escribe lo que deseas buscar.');break;case 'author-form':{const value=authorData();if(!value)return;requireUser(()=>{const business=form.dataset.kind==='business';const record={...value,id:uid(business?'b':'p'),author:state.settings.name,owner:true};if(business){record.image=value.cat==='Alimentos'?'imgFrame4':value.cat==='Artesanía'?'imgFrame2':'imgFrame3';state.businesses.unshift(record);}else state.posts.unshift(record);persist();go(business?'emprendimientos':'publicaciones');toast(business?'Emprendimiento publicado.':'Tu publicación ya está disponible.');});break;}case 'question-form':{const title=data['q-title'].trim(),description=data['q-description'].trim();if(title.length<5||description.length<10){toast('Completa un título de al menos 5 caracteres y una consulta de al menos 10.');break;}requireUser(()=>{const q={id:uid('q'),title,description,cat:data['q-cat'],author:state.settings.name,base:0};state.questions.unshift(q);persist();dialog.close();if(route==='foro')render();else go('foro');toast('Tu consulta fue publicada.');});break;}case 'reply-form':{const description=data.description.trim();if(description.length<5){toast('Escribe una respuesta de al menos 5 caracteres.');break;}requireUser(()=>{const id=form.dataset.id;if(!state.replies[id])state.replies[id]=[];state.replies[id].push({description,author:state.settings.name});persist();showQuestion(id);refreshResults();toast('Respuesta publicada.');});break;}case 'settings-form':{const name=data.name.trim();if(name.length<2){toast('Escribe un nombre de al menos 2 caracteres.');break;}state.settings={name,large:form.elements.large.checked,notices:form.elements.notices.checked};persist();render();toast('Configuración guardada.');break;}case 'report-form':{const p=state.posts.find(x=>x.id===form.dataset.id);if(state.reports.some(x=>x.postId===p.id&&x.status==='Pendiente')){toast('Esta publicación ya tiene un reporte pendiente.');dialog.close();break;}requireUser(()=>{state.reports.push({id:uid('r'),postId:p.id,title:p.title,reason:data.reason,status:'Pendiente'});persist();dialog.close();toast('Reporte registrado. Puedes revisarlo en Moderación.');});break;}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#sidebar').classList.contains('open')){$('#sidebar').classList.remove('open');$('.menu-button').setAttribute('aria-expanded','false');$('.menu-button').focus();}});
// El hash mantiene el historial Atrás/Adelante y permite abrir directamente cada sección.
navigate();
